(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzo-sj-prepa-ssrpf-j9-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzo-sj-prepa-ssrpf-j9-sfm\",\n \"titre\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J SSR / PF · Prépa D.E J9 (SFM)\",\n     \"slug\": \"prepa-ssrpf-j9-sfm\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"SSR / PF\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de l'évaluation EADS, le prestataire doit commencer la discussion par les questions les moins embarrassantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'évaluation psychosociale de l'adolescent selon l'outil EADS (Environnement, Activités, Drogues/Dépression, Sexualité), le prestataire commence toujours par les domaines les moins sensibles (environnement familial, études, loisirs) avant d'aborder les sujets intimes (sexualité, consommation de substances) afin de mettre l'adolescent en confiance.\\n\\nSource : Cours SSR-PF — Santé de la reproduction des adolescents et jeunes (SRAJ) : grille EADS.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le droit à la confidentialité est exclusivement réservé aux adultes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Tout usager des services de santé de la reproduction et de planification familiale, y compris les adolescents et les jeunes, bénéficie pleinement du droit à la confidentialité et au secret professionnel (sauf danger grave et imminent pour le mineur).\\n\\nSource : Cours SSR-PF — Droits des clients en planification familiale et SRAJ.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le terme « sexe » est utilisé seulement chez les humains.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"VARI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le « sexe » désigne les caractéristiques biologiques, anatomiques et physiologiques qui différencient les mâles et les femelles chez l'ensemble des êtres vivants (humains, animaux, végétaux), contrairement au « genre » qui est une construction sociale propre à l'être humain.\\n\\nSource : Cours SSR-PF — Concepts de base : différence entre sexe et genre.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rôle de reproduction est généralement réservé aux hommes dans la communauté.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'analyse de genre, le rôle reproductif (grossesse, accouchement, allaitement, soins aux enfants et travaux domestiques) est socialement et biologiquement assumé principalement par les femmes, tandis que les hommes sont traditionnellement cantonnés au rôle productif.\\n\\nSource : Cours SSR-PF — Approche Genre et rôles sociaux (productif, reproductif, communautaire).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les familles, les femmes sont les premières à se lever et les dernières à se coucher.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Ce constat illustre la surcharge de travail quotidienne des femmes liée au cumul des tâches domestiques, reproductives et productives dans l'analyse de l'emploi du temps selon le genre.\\n\\nSource : Cours SSR-PF — Analyse de genre : profil d'activités et charge de travail.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but de la réception est de s'assurer uniquement de la quantité des produits reçus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Lors de la réception des produits de santé de la reproduction, le contrôle porte à la fois sur la quantité livrée (conforme au bon de livraison/commande) et sur la qualité des produits (intégrité des emballages, numéros de lot, dates de péremption, conditions de conservation).\\n\\nSource : Cours SSR-PF — Gestion logistique : procédure de réception des produits.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but de la réception est de s'assurer uniquement de la quantité des produits reçus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La réception exige une double vérification quantitative et qualitative (état physique des boîtes, dates d'expiration et conformité avec le bordereau de livraison). Remarque : question en double avec la question 6 dans le sujet.\\n\\nSource : Cours SSR-PF — Gestion logistique : procédure de réception des produits.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le stock disponible et utilisable est le stock qui s'obtient après inventaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le stock disponible et utilisable (SDU) correspond à la quantité réelle de produits sains, non périmés et non avariés physiquement présents dans le magasin ou la pharmacie, telle que constatée lors de l'inventaire physique.\\n\\nSource : Cours SSR-PF — Gestion logistique : inventaire et stock disponible utilisable (SDU).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hystéromètre est indispensable dans la pose de DIU d'intervalle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avant la pose d'un DIU d'intervalle, l'hystérométrie (mesure de la profondeur et de la direction de la cavité utérine à l'aide d'un hystéromètre gradué) est une étape indispensable pour vérifier la perméabilité du canal cervical, éliminer une cavité trop petite (< 6 cm) et régler le curseur du tube inséreur.\\n\\nSource : Cours SSR-PF — Technique d'insertion du DIU d'intervalle.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU au cuivre peut être utilisé comme contraceptif d'urgence.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le DIU au cuivre (TCu 380A) est la méthode de contraception d'urgence la plus efficace (taux de succès > 99 %) lorsqu'il est inséré dans les 5 jours (120 heures) suivant un rapport sexuel non protégé, tout en assurant ensuite une contraception régulière de longue durée.\\n\\nSource : Cours SSR-PF — Contraception d'urgence (DIU au cuivre).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Si on planifie l'insertion du DIU post-placentaire après un accouchement par voie basse, la GATPA doit être proscrite.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La Gestion Active de la Troisième Phase de l'Accouchement (GATPA : injection d'ocytocine, traction contrôlée du cordon et massage utérin) doit être pratiquée systématiquement chez toutes les accouchées, y compris en cas d'insertion d'un DIU post-placentaire, car elle prévient l'hémorragie du postpartum sans empêcher la pose du DIU.\\n\\nSource : Cours SSR-PF — Insertion du DIU post-placentaire (DIUPP) et GATPA.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des signes avertisseurs en cas de ligature des trompes est la survenue des symptômes de grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Bien que la ligature des trompes soit une méthode très efficace, un rare échec expose à un risque élevé de grossesse extra-utérine (GEU) ; la survenue de signes sympathiques de grossesse, d'un retard de règles ou de douleurs pelviennes constitue donc un signe d'alerte imposant une consultation immédiate.\\n\\nSource : Cours SSR-PF — Contraception chirurgicale volontaire (signes avertisseurs).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après l'insertion post-placentaire du DIU, le prestataire ne doit pas ajuster les fils.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de l'insertion post-placentaire du DIU, l'utérus est très volumineux et les fils restent haut situés dans la cavité utérine ou le canal cervical ; il ne faut ni tirer dessus ni tenter de les couper/ajuster immédiatement, car ils descendront spontanément lors de l'involution utérine.\\n\\nSource : Cours SSR-PF — Technique d'insertion du DIU post-placentaire.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les hormones contenues dans l'anneau contraceptif sont absorbées par l'épithélium vaginal.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Placé dans le vagin, l'anneau vaginal combiné libère en continu de faibles doses d'éthinylestradiol et d'étonogestrel qui sont directement absorbées à travers la muqueuse (épithélium) vaginale pour passer dans la circulation sanguine générale.\\n\\nSource : Cours SSR-PF — L'anneau vaginal contraceptif combiné.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anneau vaginal protège contre le cancer du col de l'utérus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les contraceptifs hormonaux combinés (dont l'anneau vaginal) réduisent le risque de cancer de l'endomètre et de l'ovaire, mais ne protègent ni contre les infections à HPV ni contre le cancer du col de l'utérus.\\n\\nSource : Cours SSR-PF — Avantages non contraceptifs et limites de l'anneau vaginal.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les CHP contiennent une faible quantité d'œstrogène.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les contraceptifs hormonaux progestatifs seuls (CHP : pilules progestatives, injectables progestatifs, implants, SIU-LNG) ne contiennent exclusivement qu'un progestatif de synthèse et sont totalement dépourvus d'œstrogènes.\\n\\nSource : Cours SSR-PF — Classification des contraceptifs hormonaux (CHC vs CHP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'implant doit toujours être posé sur le bras gauche.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'implant sous-cutané s'insère à la face interne du bras non dominant de la cliente (le bras gauche chez une droitière, mais le bras droit chez une gauchère) afin de minimiser la gêne fonctionnelle après la pose.\\n\\nSource : Cours SSR-PF — Technique d'insertion des implants sous-cutanés.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'utilisation répétée de spermicides peut provoquer des ruptures de la muqueuse vaginale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'usage fréquent et répété de spermicides (notamment à base de nonoxynol-9) peut irriter et provoquer des microlésions ou ruptures de l'épithélium vaginal, ce qui augmente paradoxalement le risque de transmission du VIH chez les femmes exposées.\\n\\nSource : Cours SSR-PF — Effets secondaires et précautions d'emploi des spermicides.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La santé de la reproduction ne prend en compte que les femmes séropositives au VIH/sida.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon la définition de la CIPD (Le Caire, 1994), la santé de la reproduction concerne le bien-être physique, mental et social de tous les individus (femmes, hommes, adolescents, personnes âgées) tout au long de leur vie, quel que soit leur statut sérologique.\\n\\nSource : Cours SSR-PF — Définition et cibles de la Santé de la Reproduction.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La Sulfadoxine-Pyriméthamine est un produit de la SR.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La Sulfadoxine-Pyriméthamine (SP), utilisée dans le Traitement Préventif Intermittent (TPI) du paludisme chez la femme enceinte lors des consultations prénatales (volet maternité à moindre risque), fait partie de la liste des médicaments et produits traceurs de la Santé de la Reproduction.\\n\\nSource : Cours SSR-PF — Composantes de la SR et gestion logistique des produits de SR.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À l'adolescence des changements physiques et sociaux surviennent, cochez parmi les propositions celles qui sont du domaine social.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pilosité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Nouvelles règles d'habillement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rites de passage à l'âge adulte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Accélération de la croissance\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Développement des seins\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Nouvelles règles d'habillement ; C. Rites de passage à l'âge adulte\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les nouvelles exigences vestimentaires et les rites initiatiques ou culturels de passage à l'âge adulte relèvent des transformations sociales et culturelles de l'adolescence, tandis que la pilosité, la poussée de croissance staturale et le développement mammaire sont des transformations biologiques et physiques de la puberté.\\n\\nSource : Cours SSR-PF — Modifications physiques, psychologiques et sociales à l'adolescence.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le processus d'adoption d'un nouveau comportement ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Information, approbation, décision, action, promotion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Information, décision, approbation, action, promotion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Approbation, décision, action, information, promotion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Information, approbation, décision, action, promotion\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le processus d'adoption d'un comportement favorable à la santé suit 5 étapes chronologiques : l'Information (connaissance), l'Approbation (adhésion morale), la Décision (intention), l'Action (mise en pratique) et la Promotion (diffusion autour de soi).\\n\\nSource : Cours SSR-PF — Communication pour le Changement de Comportement (CCC).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, relevez celle qui est une cause de violence hospitalière ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Indisponibilité du personnel soignant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mauvais traitement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inégalité dans la distribution des postes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Inégalité dans les prises des décisions familiales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Mauvais traitement\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les violences hospitalières et obstétricales s'expriment directement par les mauvais traitements infligés aux patients (brutalité verbale ou physique, humiliation, manque de respect de l'intimité et soins sans consentement).\\n\\nSource : Cours SSR-PF — Violences Basées sur le Genre (violences institutionnelles).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la bonne séquence des étapes dans la chaîne logistique pharmaceutique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Commande - Réception - Stockage - Distribution\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Stockage - Commande - Réception - Distribution\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réception - Stockage - Commande - Distribution\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Commande - Réception - Stockage - Distribution\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au niveau d'une structure sanitaire, le cycle opérationnel d'approvisionnement suit l'ordre logique suivant : estimation des besoins et Commande, Réception et contrôle des produits livrés, Stockage dans de bonnes conditions, puis Distribution/dispensation aux clients.\\n\\nSource : Cours SSR-PF — Cycle de la chaîne logistique des produits de SR.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À quoi sert le stock de sécurité dans une pharmacie de santé de la reproduction ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réduire les coûts de stockage\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prévenir les ruptures de stock\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Éviter les surstockages\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Prévenir les ruptures de stock\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le stock de sécurité (ou stock tampon) est une réserve minimale maintenue en permanence pour faire face aux retards imprévus de livraison ou à une hausse soudaine de la consommation, afin d'éviter toute rupture de stock.\\n\\nSource : Cours SSR-PF — Niveaux de stock en gestion logistique.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les clientes ci-dessous, quelle est celle qui peut recevoir le DIU ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Zransseu est au 28ème jour du cycle menstruel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Gnonhebla est au 18ème jour du cycle menstruel\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Guela est à la veille des menstrues\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Guela est à la veille des menstrues\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon la correction nationale de la Prépa DE (les J), Guela étant à la veille de ses menstrues (hors période ovulatoire et sans retard de règles évocateur de grossesse, ou dans le cadre des 12 premiers/derniers jours selon l'approche classique), elle peut recevoir le DIU.\\n\\nSource : Cours SSR-PF — Critères d'insertion du DIU d'intervalle.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mariane a reçu le DIU le 12 septembre le jour de son accouchement, à partir de quelle date elle pourra faire vérifier la descente des fils du DIU au CSU ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Quatorze semaines après l'insertion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Six semaines après l'insertion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Douze semaines après l'insertion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Six semaines après l'insertion\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après une insertion du DIU dans le post-partum immédiat, la visite de contrôle systématique est programmée à 6 semaines après l'accouchement (coïncidant avec la consultation post-natale) afin de vérifier la descente des fils au spéculum et de les recouper à la bonne longueur.\\n\\nSource : Cours SSR-PF — Calendrier de suivi du DIU post-partum (DIUPP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel des énoncés suivants est indispensable à chaque visite de suivi d'une cliente sous DIU ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vérifier sa compréhension sur le DIU et lui demander si elle a des questions.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dire à la cliente pour combien de temps elle devrait garder son DIU.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Effectuer un examen gynécologique pour comparer les fils ou une partie du DIU extériorisée.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vérifier sa compréhension sur le DIU et lui demander si elle a des questions.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de toute visite de suivi sous DIU, l'étape systématique et indispensable consiste à s'enquérir de la satisfaction de la cliente, vérifier sa bonne compréhension de la méthode et répondre à ses questions ou préoccupations ; l'examen pelvien au spéculum n'est pas systématique à chaque visite en l'absence de symptômes.\\n\\nSource : Cours SSR-PF — Visites de suivi des utilisatrices de DIU.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel des énoncés suivants décrit la catégorie prudence dans la stérilisation masculine ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Attendre que l'état pathologique soit évalué\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il n'y a aucune raison d'accepter la méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Offrir avec beaucoup de précautions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Offrir avec beaucoup de précautions\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans la classification OMS pour la stérilisation chirurgicale (A-P-D-R), la catégorie « Prudence » (P) signifie que l'intervention peut être pratiquée dans un établissement de routine, mais en prenant des précautions et préparations supplémentaires adaptées à l'état du patient (ex. hydrocèle, varicocèle, diabète). « Attendre que l'état soit évalué » correspond à la catégorie « Différer ».\\n\\nSource : Cours SSR-PF — Critères d'éligibilité médicale pour la vasectomie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la contraception d'urgence, quelle est la période d'administration de Ovrette ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dans les 120 heures après les rapports sexuels\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dans les 72 heures après les rapports sexuels\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dans les 48 heures après les rapports sexuels\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Dans les 72 heures après les rapports sexuels\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les pilules progestatives utilisées en contraception d'urgence (lévonorgestrel ou norgestrel tel que l'Ovrette® selon le protocole de rattrapage) doivent être administrées le plus tôt possible et au plus tard dans les 72 heures (3 jours) suivant le rapport sexuel non protégé.\\n\\nSource : Cours SSR-PF — Protocoles de contraception d'urgence hormonale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les contraceptifs suivants, quel est celui que le prestataire doit proscrire après un avortement septique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ovrette\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"DIU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Jadelle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. DIU\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après un avortement septique (compliqué d'infection pelvienne), l'insertion immédiate d'un DIU est formellement proscrite (catégorie 4 de l'OMS), alors que les contraceptifs progestatifs (Ovrette, implant Jadelle) peuvent être initiés sans risque.\\n\\nSource : Cours SSR-PF — Contraception dans les soins après avortement (SAA).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Gnohela sous COC doit prendre un BARBITURIQUE ; pourquoi doit-elle prendre une méthode d'appoint ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Effet contraceptif diminué des COC avec la prise du barbiturique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Effet contraceptif des COC augmenté avec la prise du barbiturique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Effet du barbiturique diminué avec la prise des COC\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Effet contraceptif diminué des COC avec la prise du barbiturique\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les barbituriques (comme le phénobarbital, ainsi que la rifampicine et certains anticonvulsivants) sont de puissants inducteurs enzymatiques hépatiques qui accélèrent le métabolisme et l'élimination des hormones des COC, diminuant ainsi leur efficacité contraceptive et imposant une méthode d'appoint (préservatif).\\n\\nSource : Cours SSR-PF — Interactions médicamenteuses des contraceptifs oraux combinés.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque l'utilisatrice des COP prend le comprimé du jour avec plus de 3 heures de retard, que doit-elle faire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Continuer la plaquette sans prendre de dispositions particulières.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Arrêter la prise des pilules et attendre les règles pour entamer une autre plaquette.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Utiliser une méthode d'appoint si elle a des rapports sexuels dans les 48 heures.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Utiliser une méthode d'appoint si elle a des rapports sexuels dans les 48 heures.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pour les pilules progestatives seules (COP), un retard supérieur à 3 heures annule temporairement l'imperméabilité de la glaire cervicale : la cliente doit prendre immédiatement le comprimé oublié, continuer la plaquette et utiliser une méthode d'appoint (ou s'abstenir) pendant les 48 heures suivantes.\\n\\nSource : Cours SSR-PF — Gestion de l'oubli des contraceptifs oraux progestatifs (COP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une cliente sous contraceptif oral progestatif qui a des spottings doit :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Revenir au centre de PF\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Arrêter la prise des comprimés\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Changer de méthode contraceptive\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Revenir au centre de PF\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Bien que les saignements irréguliers (spottings) soient fréquents et bénins sous contraceptifs progestatifs seuls, la cliente ne doit pas arrêter brutalement ses pilules d'elle-même ; elle doit revenir au centre de PF pour être rassurée, examinée (éliminer une grossesse ou une infection) et bénéficier d'une prise en charge adaptée.\\n\\nSource : Cours SSR-PF — Gestion des effets secondaires des contraceptifs progestatifs.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les gestes à proscrire lors de l'utilisation du condom ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Utiliser un nouveau condom à chaque rapport sexuel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Enfiler le condom sur le pénis en érection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ouvrir le sachet de préservatif avec une paire de ciseaux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Lubrifier avec de la vaseline\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Vérifier la date de péremption\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Ouvrir le sachet de préservatif avec une paire de ciseaux ; D. Lubrifier avec de la vaseline\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Il est formellement proscrit d'ouvrir l'emballage avec des ciseaux, les dents ou un objet tranchant (risque de déchirer le latex) et d'utiliser des lubrifiants à base d'huile comme la vaseline (qui altèrent et fragilisent le latex, favorisant la rupture du préservatif).\\n\\nSource : Cours SSR-PF — Précautions d'emploi du préservatif masculin.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les indicateurs suivants décrivent le dynamisme de la population, quel est celui qui prend en compte le taux de mortalité infantile ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Indicateur socio-économique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Indicateur sanitaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Indicateur démographique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Indicateur sanitaire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le taux de mortalité infantile est classé parmi les indicateurs sanitaires permettant d'apprécier l'état de santé de la mère et de l'enfant ainsi que la qualité de l'offre de soins.\\n\\nSource : Cours SSR-PF — Indicateurs de santé de la reproduction.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, quels sont les obstacles économiques de la PF ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le coût des services de PF\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les mariages précoces\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'effet de mode\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le manque de moyens financiers.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les coutumes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le coût des services de PF ; D. Le manque de moyens financiers.\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Parmi les obstacles à l'utilisation des services de planification familiale, le coût des prestations/produits (et du transport) ainsi que le manque de moyens financiers (pauvreté des ménages) relèvent des obstacles économiques, tandis que les mariages précoces et les coutumes sont des obstacles socioculturels.\\n\\nSource : Cours SSR-PF — Obstacles à l'utilisation des services de planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les critères médicaux d'éligibilité permettent de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Classer les méthodes en fonction de leur mode d'action\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"D'améliorer la qualité et l'utilisation des méthodes et services de PF.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prendre en charge les effets secondaires de la méthode\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. D'améliorer la qualité et l'utilisation des méthodes et services de PF.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les critères de recevabilité médicale établis par l'OMS visent à lever les barrières médicales injustifiées et à garantir la sécurité des clientes, améliorant ainsi l'accès, la qualité et l'utilisation des services de planification familiale.\\n\\nSource : Cours SSR-PF — Objectifs des critères d'éligibilité médicale de l'OMS.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les catégories pour la stérilisation féminine et les catégories pour les méthodes basées sur la connaissance de la fécondité, la catégorie accepter signifie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les avantages l'emportent généralement sur les risques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Offrir la méthode avec beaucoup de précautions\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aucune raison médicale de refuser la méthode\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Aucune raison médicale de refuser la méthode\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans la grille A-P-D-R (Accepter, Prudence, Différer, Référer) propre à la stérilisation chirurgicale et aux méthodes basées sur la connaissance de la fécondité, la catégorie « Accepter » (A) signifie qu'il n'existe aucune raison médicale de refuser la méthode au client dans un cadre de soins habituel.\\n\\nSource : Cours SSR-PF — Classification OMS (A-P-D-R) pour la CCV et les MBCF.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, quelle est celle qui va à l'encontre d'un choix libre et éclairé du client ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La non disponibilité de la gamme des méthodes contraceptives\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le respect de tout client\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Absence de matériel d'IEC/CCC\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La non disponibilité de la gamme des méthodes contraceptives\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le choix libre et éclairé exige que le client puisse choisir volontairement parmi un éventail complet de méthodes contraceptives disponibles ; la rupture ou l'indisponibilité de la gamme des méthodes restreint directement cette liberté de choix.\\n\\nSource : Cours SSR-PF — Droits du client et choix libre et éclairé.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lesquelles des questions suivantes sont des questions ouvertes ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vous rappelez-vous de ce qu'il faut faire si vous avez oublié une pilule ?\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Que pensez-vous de l'utilisation de la pilule ?\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réalisez-vous que la stérilisation féminine est permanente ?\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Que ressentiriez-vous de ne pas avoir d'autres enfants ?\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Avez-vous entendu parler du DIU ?\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Que pensez-vous de l'utilisation de la pilule ? ; D. Que ressentiriez-vous de ne pas avoir d'autres enfants ?\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Une question ouverte invite le client à s'exprimer librement sur ses opinions, sentiments ou expériences (« Que pensez-vous... ? », « Que ressentiriez-vous... ? »), contrairement aux questions fermées auxquelles on répond simplement par « oui » ou par « non ».\\n\\nSource : Cours SSR-PF — Techniques de communication et d'entretien en counseling.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour la plupart des clients, la meilleure méthode de PF est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Celle que le prestataire de santé pense être la meilleure pour un client particulier\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Celle que le client choisit après avoir pris connaissance de toutes les méthodes disponibles.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Celle qui est la plus efficace\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Celle qui convient le mieux au prestataire.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Celle que le client choisit après avoir pris connaissance de toutes les méthodes disponibles.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon le principe fondamental du counseling en planification familiale, la meilleure méthode contraceptive est celle que le client (ou le couple) choisit librement de manière éclairée après avoir reçu des informations complètes sur toutes les méthodes éligibles, car elle garantit la meilleure observance et continuité d'utilisation.\\n\\nSource : Cours SSR-PF — Principes fondamentaux du counseling en PF.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme Zou qui utilise la méthode des jours fixes a vu ses menstrues le 12 juin ; à quelle date l'anneau noir était sur la 9ème perle blanche ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le 24 juin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le 19 juin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le 27 juin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le 27 juin\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Sur le Collier du Cycle, les 7 premières perles (1 perle rouge + 6 perles marron) correspondent aux jours 1 à 7 du cycle, et les perles blanches débutent au 8e jour (1re perle blanche = J8). La 9e perle blanche correspond donc au 8 + 8 = 16e jour du cycle. Avec J1 le 12 juin, le 16e jour correspond au 12 + 15 = 27 juin.\\n\\nSource : Cours SSR-PF — Utilisation et calcul sur le Collier du Cycle (MJF).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme GUEL a pu identifier son cycle court qui a une durée de 28 jours et son cycle long 30 jours. Quelle est la durée de sa période fertile ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"12 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"14 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 10 jours\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"D'après la méthode du calendrier d'Ogino-Knaus : début de la période fertile = cycle court − 18 = 28 − 18 = 10e jour ; fin de la période fertile = cycle long − 11 = 30 − 11 = 19e jour. Du 10e au 19e jour inclus, la durée de la période fertile est de (19 − 10) + 1 = 10 jours.\\n\\nSource : Cours SSR-PF — Calcul de la période fertile selon Ogino-Knaus.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme Zébré utilisatrice de la méthode de la température basale du corps, elle doit savoir que la période non fertile part :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Du 5ème jour après la montée thermique jusqu'aux prochaines règles.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Du 4ème jour après la montée thermique jusqu'aux prochaines règles.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Du 6ème jour après la montée thermique jusqu'aux prochaines règles.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Du 4ème jour après la montée thermique jusqu'aux prochaines règles.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans la méthode des températures basales du corps, l'ovulation est confirmée après 3 jours consécutifs de plateau thermique élevé (+0,2 à +0,5 °C par rapport aux 6 températures basses précédentes) ; la phase post-ovulatoire non fertile débute donc le soir du 3e jour ou au 4ème jour de température haute jusqu'aux prochaines règles.\\n\\nSource : Cours SSR-PF — Méthode de la température basale du corps (TBC).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 : Mlle Necemon étudiante à l'INFAS est sous COC ; en allant en stage dans la ville où réside son mari a oublié de prendre sa plaquette de pilules. Cependant elle se rappelle qu'elle avait entamé les comprimés de couleur marron.\",\n       \"text\": \"Est-ce qu'elle peut contracter une grossesse si le jour de son arrivée elle a des rapports sexuels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"NON\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"OUI\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. NON\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les 7 comprimés de couleur marron d'une plaquette de 28 comprimés sont des comprimés inactifs (placebo contenant du fer) correspondant à la période d'arrêt entre deux plaquettes : tant que la patiente a pris régulièrement les 21 comprimés actifs précédents et entame la plaquette suivante à la date prévue, elle reste protégée pendant toute la semaine des comprimés marron.\\n\\nSource : Cours SSR-PF — Utilisation des plaquettes de COC à 28 comprimés.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 : Mlle Necemon étudiante à l'INFAS est sous COC ; en allant en stage dans la ville où réside son mari a oublié de prendre sa plaquette de pilules. Cependant elle se rappelle qu'elle avait entamé les comprimés de couleur marron.\",\n       \"text\": \"Quelle doit être sa conduite à tenir ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Utiliser une méthode de barrière mécanique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prendre une pilule du lendemain\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pas de dispositions particulières\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Pas de dispositions particulières\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'oubli des comprimés inactifs (de couleur marron) n'ayant aucune incidence sur l'efficacité contraceptive, aucune mesure particulière ni contraception d'urgence n'est requise durant cette semaine, à condition de débuter une nouvelle plaquette dès la fin des 7 jours.\\n\\nSource : Cours SSR-PF — Conduite à tenir en cas d'oubli des comprimés placebos (marron).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 : Mlle Necemon étudiante à l'INFAS est sous COC ; en allant en stage dans la ville où réside son mari a oublié de prendre sa plaquette de pilules. Cependant elle se rappelle qu'elle avait entamé les comprimés de couleur marron.\",\n       \"text\": \"Quel est le mode d'action des pilules de Mlle Necemon ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bloque l'ovulation, épaissit la glaire cervicale, rend l'endomètre impropre à la nidation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bloque l'ovulation, tue les spermatozoïdes, rend l'endomètre impropre à la nidation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Bloque partiellement l'ovulation, tue les spermatozoïdes, rend l'endomètre impropre à la nidation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Bloque l'ovulation, épaissit la glaire cervicale, rend l'endomètre impropre à la nidation\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les contraceptifs oraux combinés (COC) agissent à trois niveaux complémentaires : ils bloquent l'ovulation (action antigonadotrope centrale inhibant le pic de LH), épaississent la glaire cervicale (empêchant l'ascension des spermatozoïdes) et atrophient l'endomètre (le rendant impropre à la nidation). Ils n'ont pas d'action spermicide directe.\\n\\nSource : Cours SSR-PF — Mécanisme d'action des contraceptifs oraux combinés.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 : Mlle Necemon étudiante à l'INFAS est sous COC ; en allant en stage dans la ville où réside son mari a oublié de prendre sa plaquette de pilules. Cependant elle se rappelle qu'elle avait entamé les comprimés de couleur marron.\",\n       \"text\": \"À quel moment Mlle Necemon doit débuter une nouvelle plaquette de pilules ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"À la fin des menstrues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dès la survenue des menstrues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le lendemain de la prise du dernier comprimé marron\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le lendemain de la prise du dernier comprimé marron\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avec une présentation de 28 comprimés, les plaquettes s'enchaînent sans aucun jour d'interruption : la nouvelle plaquette doit impérativement être débutée le lendemain du 7e comprimé marron (c'est-à-dire au 8e jour après le dernier comprimé actif), que les saignements de privation soient terminés ou non.\\n\\nSource : Cours SSR-PF — Enchaînement des plaquettes de COC (28 comprimés).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__49\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 : Mlle Necemon étudiante à l'INFAS est sous COC ; en allant en stage dans la ville où réside son mari a oublié de prendre sa plaquette de pilules. Cependant elle se rappelle qu'elle avait entamé les comprimés de couleur marron.\",\n       \"text\": \"En plus du COC, quelle méthode Mlle Necemon peut prendre pour éviter de contracter une IST\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"DIU\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fémidon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Implant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Fémidon\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Pour assurer la double protection (prévention des grossesses par les COC + protection contre les IST/VIH), elle doit associer une méthode barrière mécanique telle que le préservatif masculin ou le préservatif féminin (Fémidon®). Le DIU et l'implant ne protègent pas contre les IST.\\n\\nSource : Cours SSR-PF — La double protection (préservatif féminin / Fémidon).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__50\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 : Mme Droh est une jeune femme de 22 ans avec 4 enfants. Elle voudrait une méthode de très longue durée, réversible qui lui sera administrée après la délivrance.\",\n       \"text\": \"À quelle méthode pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"DIU au cuivre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ligature des trompes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"MAMA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. DIU au cuivre\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le dispositif intra-utérin (DIU) au cuivre TCu 380A est la seule méthode contraceptive réversible de très longue durée pouvant être insérée immédiatement après la délivrance (la ligature des trompes est définitive/irréversible, et la MAMA n'est valable que 6 mois).\\n\\nSource : Cours SSR-PF — Planification familiale du post-partum immédiat.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__51\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 : Mme Droh est une jeune femme de 22 ans avec 4 enfants. Elle voudrait une méthode de très longue durée, réversible qui lui sera administrée après la délivrance.\",\n       \"text\": \"Quelle est la durée d'action du contraceptif ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"12 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"À vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 12 ans\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le dispositif intra-utérin au cuivre TCu 380A assure une protection contraceptive efficace pendant une durée maximale de 10 à 12 ans (retenue à 12 ans dans les normes actualisées de PF).\\n\\nSource : Cours SSR-PF — Caractéristiques et durée d'efficacité du DIU TCu 380A.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__52\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 : Mme Droh est une jeune femme de 22 ans avec 4 enfants. Elle voudrait une méthode de très longue durée, réversible qui lui sera administrée après la délivrance.\",\n       \"text\": \"Après l'accouchement normal, à quels moments le prestataire pourra lui administrer la méthode ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dans les 10 minutes qui suivent l'accouchement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De 48 heures à 4 semaines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un an après l'accouchement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"6 semaines après l'accouchement\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Dans les 48 heures qui suivent l'accouchement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Dans les 10 minutes qui suivent l'accouchement ; E. Dans les 48 heures qui suivent l'accouchement\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans les suites immédiates d'un accouchement par voie basse, le DIU peut être inséré soit dans les 10 minutes suivant l'expulsion du placenta (insertion post-placentaire), soit dans les 48 heures suivant l'accouchement (insertion post-partum immédiate) ; entre 48 heures et 4 semaines, la pose est contre-indiquée.\\n\\nSource : Cours SSR-PF — Créneaux d'insertion du DIU dans le post-partum.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 : Mme Droh est une jeune femme de 22 ans avec 4 enfants. Elle voudrait une méthode de très longue durée, réversible qui lui sera administrée après la délivrance.\",\n       \"text\": \"Comment appelle-t-on ces deux types d'insertion ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Insertion per césarienne\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Insertion d'intervalle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Insertion post-partum immédiate\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Insertion per césarienne\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Insertion post-placentaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Insertion post-partum immédiate ; E. Insertion post-placentaire\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L'insertion effectuée dans les 10 minutes suivant la délivrance s'appelle l'insertion postplacentaire, et celle effectuée après ces 10 minutes jusqu'à 48 heures après l'accouchement s'appelle l'insertion post-partum immédiate.\\n\\nSource : Cours SSR-PF — Terminologie des insertions du DIU du post-partum.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j9-sfm__54\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 : Mme Droh est une jeune femme de 22 ans avec 4 enfants. Elle voudrait une méthode de très longue durée, réversible qui lui sera administrée après la délivrance.\",\n       \"text\": \"Après l'évaluation la condition suivante ne permet pas d'insérer le DIU à Mme Droh ; quelle est celle-ci ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accouchement gémellaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rupture artificielle des membranes de moins de quatre heures.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hémorragie du post-partum non maîtrisée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Épisiotomie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Hémorragie du post-partum non maîtrisée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les contre-indications spécifiques à la pose immédiate d'un DIU dans le post-partum sont l'infection ovulaire/chorioamniotite (rupture des membranes > 18 heures), la fièvre puerpérale et l'hémorragie du post-partum non maîtrisée (qui impose d'abord l'hémostase et la réanimation). L'accouchement gémellaire, une rupture des membranes de moins de 4 heures et une épisiotomie réparée n'empêchent pas la pose.\\n\\nSource : Cours SSR-PF — Contre-indications du DIU post-partum (DIUPP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J9 (SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
